class Solution
{
    unordered_map<string, bool> memo;
    bool win(string state)
    {
        if (memo.count(state))
        {
            return memo[state];
        }
        for (int i = 0; i + 1 < (int)state.size(); ++i)
        {
            if (state[i] == '+' && state[i + 1] == '+')
            {
                state[i] = state[i + 1] = '-';
                bool opponentWins = win(state);
                state[i] = state[i + 1] = '+';
                if (!opponentWins)
                {
                    return memo[state] = true;
                }
            }
        }
        return memo[state] = false;
    }
public:
    bool canWin(string currentState)
    {
        return win(currentState);
    }
};
